<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue';import {useEditor} from '../stores/editor';import {qualityProfiles} from '../render/quality';import {PlannerScene,type SceneStats} from '../render/scene';
const e=useEditor(),host=ref<HTMLDivElement>(),error=ref(''),cutaway=ref(true),stats=ref<SceneStats>();let scene:PlannerScene|undefined;
onMounted(()=>{try{scene=new PlannerScene(host.value!,{warning:message=>e.error=message,select:id=>{e.selected={kind:'furniture',id};},move:(id,x,z)=>{e.edit('Переместить мебель в 3D',p=>{const f=p.variants.find(v=>v.id===p.activeVariantId)!.furniture.find(f=>f.id===id)!;f.x=x;f.z=z;});},stats:s=>stats.value=s});scene.setQuality(e.quality);scene.update(e.document,e.assets);scene.setMode(e.mode==='2d'?'3d':e.mode);scene.select(e.selected?.kind==='furniture'?e.selected.id:undefined);}catch(reason){scene?.dispose();scene=undefined;error.value='Не удалось запустить 3D. План и редактирование в 2D доступны. '+(reason as Error).message;}});
watch(()=>e.quality,q=>{localStorage.setItem('house-planner-quality',String(q));scene?.setQuality(q);});
watch([()=>e.document,()=>e.assets],([p,assets])=>scene?.update(p,assets));watch(()=>e.mode,m=>{if(m!=='2d')scene?.setMode(m);});watch(()=>e.selected,s=>scene?.select(s?.kind==='furniture'?s.id:undefined));onBeforeUnmount(()=>scene?.dispose());
</script>
<template><div class="canvas-shell"><div ref="host" class="canvas-host scene-host"/><div v-if="error" class="empty-plan" role="alert"><p>{{error}}</p><button @click="e.mode='2d'">Открыть 2D</button></div><div v-else class="viewport-tools"><select aria-label="Качество 3D" v-model.number="e.quality"><option v-for="q in qualityProfiles" :value="q.level">{{q.level}} · {{q.name}}</option></select><button @click="scene?.fit()">Весь дом</button><button v-if="e.mode!=='walk'" @click="cutaway=scene?.toggleWalls()??true">{{cutaway?'Полные стены':'Срез стен'}}</button></div><div v-if="stats" class="scene-stats" data-testid="scene-stats" :data-geometries="stats.geometries" :data-textures="stats.textures" :data-triangles="stats.triangles">{{stats.triangles.toLocaleString('ru')}} треугольников · {{stats.drawCalls}} вызовов · {{stats.frameMs.toFixed(1)}} мс/кадр · {{stats.geometries}} геометрий · {{stats.textures}} текстур · ≈{{(stats.estimatedBytes/1048576).toFixed(0)}} МБ (оценка)</div><div class="viewport-help">{{e.mode==='walk'?'WASD / стрелки — ходьба · Потяните мышью — осмотр':'Мышь — вращение · Правая кнопка — сдвиг · Колесо — масштаб · Потяните предмет — перенос'}}</div></div></template>
